  "description": "Town of Whitby's Whitby Lights the Night Festival at Civic Park — official tree-lighting ceremony at 5:30 PM, over 200,000 festive lights, live entertainment, and a visit from Santa. The Whitby Farmers' Market Christmas Market runs as part of the festival, in front of the Whitby Civic Recreation Complex (market hours 4–9 PM). Vendors take part through the Whitby Farmers' Market (Durham Region Farmers' Market Association), Market Manager Sara Demoe: vendors must produce at least 70% of the products they sell, non-seasonal vendors pay a $20 non-refundable membership, and vendors supply their own 10x10 tent, tables, and displays.\nTheme: Christmas / holiday season\nFee: not stated by organizer\nHow to apply: https://www.whitbyfarmersmarket.ca/\nHours: 4:00 PM – 9:00 PM\nAttractions: Official tree-lighting ceremony at 5:30 PM, visit from Santa, 200,000+ festive lights, live entertainment and strolling performers, cookie decorating, seasonal crafts and family activities, sensory room, Whitby Farmers' Christmas Market, Town Trolley and parking shuttle\nSource: https://www.whitby.ca/explore-and-enjoy/events-and-festivals/attend-an-event/whitby-lights-the-night/",
